def get_promise_item_amazon_identifier(
    book: dict[str, Any],
) -> tuple[str, str] | None:
    """Return the preferred Amazon lookup id and its type for an incomplete item."""
    if isbn_10 := _first_identifier(book.get('isbn_10')):
        return isbn_10, 'isbn'

    identifiers = book.get('identifiers')
    amazon_ids = identifiers.get('amazon') if isinstance(identifiers, dict) else None
    if asin := _first_identifier(amazon_ids):
        if asin.upper().startswith('B'):
            return asin, 'asin'

    source_records = book.get('source_records')
    if isinstance(source_records, str):
        source_records = [source_records]
    if isinstance(source_records, (list, tuple)):
        for source_record in source_records:
            if isinstance(source_record, str) and source_record.startswith('amazon:B'):
                return source_record.split(':', 1)[1], 'asin'
    return None


