def stage_b_asins_for_import(olbooks: list[dict[str, Any]]) -> None:
    """Stage incomplete promise items so import can supplement their metadata."""
    for book in olbooks:
        if not is_incomplete_promise_item(book):
            continue

        if not (lookup := get_promise_item_amazon_identifier(book)):
            continue

        identifier, id_type = lookup
        try:
            get_amazon_metadata(id_=identifier, id_type=id_type)
        except Exception:  # noqa: BLE001
            logger.exception("Amazon metadata lookup failed for %s", identifier)


