def normalize_import_placeholders(record: dict[str, Any]) -> None:
    """Remove placeholder values used by legacy promise-item imports in place."""
    if record.get("publishers") == ["????"]:
        record.pop("publishers")
    if record.get("authors") == [{"name": "????"}]:
        record.pop("authors")
    if record.get("publish_date") == "????":
        record.pop("publish_date")


def is_complete_record(record: dict[str, Any]) -> bool:
    """Return whether title, at least one named author, and publish date exist."""

    def has_text(value: Any) -> bool:
        return isinstance(value, str) and bool(value.strip()) and value.strip() != "????"

    authors = record.get("authors")
    has_author = isinstance(authors, list) and any(
        has_text(author.get("name")) if isinstance(author, dict) else has_text(author)
        for author in authors
    )
    return (
        has_text(record.get("title"))
        and has_author
        and has_text(record.get("publish_date"))
    )


