def get_promise_item_amazon_identifier(
    book: dict[str, Any],
) -> tuple[str, str] | None:
    """Return the preferred Amazon lookup id and its type for an incomplete item."""
    if isbn_10 := _first_identifier(book.get('isbn_10')):
        return isbn_10, 'isbn'

    identifiers = book.get('identifiers')
    amazon_ids = identifiers.get('amazon') if isinstance(identifiers, dict) else None
    if asin := _first_identifier(amazon_ids):
        if asin.upper().startswith('B'):
            return asin, 'asin'

    source_records = book.get('source_records')
    if isinstance(source_records, str):
        source_records = [source_records]
    if isinstance(source_records, (list, tuple)):
        for source_record in source_records:
            if isinstance(source_record, str) and source_record.startswith('amazon:B'):
                return source_record.split(':', 1)[1], 'asin'
    return None


def record_promise_import_metrics(books: list[dict[str, Any]]) -> None:
    if not stats.client:
        return
    stats.gauge('ol.promise_import.total_items', len(books))
    stats.gauge(
        'ol.promise_import.incomplete_items',
        sum(is_incomplete_promise_item(book) for book in books),
    )


def stage_b_asins_for_import(olbooks: list[dict[str, Any]]) -> None:
    """Stage incomplete promise items so import can supplement their metadata."""
    for book in olbooks:
        if not is_incomplete_promise_item(book):
            continue

        if not (lookup := get_promise_item_amazon_identifier(book)):
            continue

        identifier, id_type = lookup
        try:
            get_amazon_metadata(id_=identifier, id_type=id_type)
        except Exception:  # noqa: BLE001
            logger.exception("Amazon metadata lookup failed for %s", identifier)


def batch_import(promise_id, batch_size=1000, dry_run=False):
    url = "https://archive.org/download/"
    date = promise_id.split("_")[-1]
    resp = requests.get(f"{url}{promise_id}/DailyPallets__{date}.json", stream=True)
    olbooks_gen = (
        map_book_to_olbook(book, promise_id) for book in ijson.items(resp.raw, 'item')
    )

    # Note: dry_run won't include BookWorm data.
    if dry_run:
        for book in olbooks_gen:
            print(json.dumps(book), flush=True)
        return

    olbooks = list(olbooks_gen)

    record_promise_import_metrics(olbooks)

    # Stage incomplete records so load() can supplement their metadata.
    stage_b_asins_for_import(olbooks)

    batch = Batch.find(promise_id) or Batch.new(promise_id)
    # Find just-in-time import candidates for incomplete records only.
    jit_candidates = []
    for book in olbooks:
        if not is_incomplete_promise_item(book):
            continue
        if isbn_13 := _first_identifier(book.get('isbn_13')):
            jit_candidates.append(isbn_13)
        if lookup := get_promise_item_amazon_identifier(book):
            jit_candidates.append(lookup[0])
    if jit_candidates:
        jit_candidates = list(dict.fromkeys(jit_candidates))
        ImportItem.bulk_mark_pending(jit_candidates)
    batch_items = [{'ia_id': b['local_id'][0], 'data': b} for b in olbooks]
    for i in range(0, len(batch_items), batch_size):
        batch.add_items(batch_items[i : i + batch_size])


